WITH gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS session_start_flag FROM transactions), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT CASE WHEN session_no >= 9 THEN 'PREMIUM' ELSE 'STANDARD' END AS session_no_tier, DATE_TRUNC('WEEK', txn_time) AS week_start, ROUND(SUM(session_start_flag) / NULLIF(COUNT(CASE WHEN txn_type = 'DEBIT' THEN 1 END), 0), 2) AS session_start_flag_per_debit, SUM(CASE WHEN txn_type = 'REFUND' THEN session_start_flag ELSE 0 END) AS refund_session_start_flag, MAX(txn_time) AS ended_at, MAX(txn_time) AS last_txn_time, PERCENTILE_APPROX(amount, 0.5) AS amount_p50, RANK() OVER (PARTITION BY CASE WHEN session_no >= 9 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY PERCENTILE_APPROX(amount, 0.5) DESC) AS amount_p50_rank FROM sessionized GROUP BY session_no_tier, week_start
